import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, {alpha} participants tackle the following generalized system. Let x, y, z be positive real numbers satisfying x^{a} y^{b} z^{c} = {k}. Furthermore, x^{a} + 1/z^{c} = {A_num}/{A_den} and y^{b} + 1/x^{a} = {B_num}/{B_den}. Write z^{c} + 1/y^{b} as m/n in lowest terms, and report the value of m + n.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate integers X, Y, Z representing X = x^a, Y = y^b, Z = z^c.
# Then k = XYZ, A = X + 1/Z, B = Y + 1/X. The target is C = Z + 1/Y.
# We ensure non-triviality: at least one exponent > 1, denominators > 1, k >= 2, and the final C not integer.
def gcd(u, v):
  while v:
    u, v = v, u % v
  return abs(u)
for _ in range(1000):
  alpha = rng.randint(40, 200)
  a = rng.randint(1, 3)
  b = rng.randint(1, 3)
  c = rng.randint(1, 3)
  # Ensure increased difficulty: at least one exponent > 1
  if a == 1 and b == 1 and c == 1:
    continue
  X = rng.randint(2, 12)
  Y = rng.randint(2, 12)
  Z = rng.randint(2, 12)
  k = X * Y * Z
  # Build A = X + 1/Z = (XZ + 1)/Z
  A_num = X * Z + 1
  A_den = Z
  # Build B = Y + 1/X = (YX + 1)/X
  B_num = Y * X + 1
  B_den = X
  # Compute target C directly for a consistency check: C = Z + 1/Y = (ZY + 1)/Y
  C_num = Z * Y + 1
  C_den = Y
  # Non-trivial: denominator > 1 and fraction not an integer
  if C_den <= 1:
    continue
  if C_num % C_den == 0:
    continue
  # Additional safety: AB - 1 should be non-zero (it will be positive with our choices, but we check anyway)
  AB_num = A_num * B_num
  AB_den = A_den * B_den
  AB_minus_1_num = AB_num - AB_den
  if AB_minus_1_num == 0:
    continue
  # All good; return assignment
  return {
    'alpha': alpha,
    'a': a,
    'b': b,
    'c': c,
    'k': k,
    'A_num': A_num,
    'A_den': A_den,
    'B_num': B_num,
    'B_den': B_den,
    # hidden values for internal verification
    '_X': X,
    '_Y': Y,
    '_Z': Z,
    '_C_num': C_num,
    '_C_den': C_den
  }
# Fallback (unlikely)
return {
  'alpha': 100,
  'a': 2,
  'b': 1,
  'c': 2,
  'k': 60,
  'A_num': 25,
  'A_den': 6,
  'B_num': 13,
  'B_den': 5,
  '_X': 4,
  '_Y': 5,
  '_Z': 3,
  '_C_num': 16,
  '_C_den': 5
}

    def verifier(assign):
# Recompute the required value using the derived identity
# For X = x^a, Y = y^b, Z = z^c with XYZ = k and A = X + 1/Z, B = Y + 1/X,
# one can prove: C = Z + 1/Y = (A + B + k + 1/k) / (AB - 1).
# We return m + n where C = m/n in lowest terms.
def gcd(u, v):
  while v:
    u, v = v, u % v
  return abs(u)
# Validate required keys
req = ['alpha','a','b','c','k','A_num','A_den','B_num','B_den']
for key in req:
  if key not in assign:
    # Missing required data
    return (False, None)
a = assign['a']; b = assign['b']; c = assign['c']
k = assign['k']
A_num = assign['A_num']; A_den = assign['A_den']
B_num = assign['B_num']; B_den = assign['B_den']
# Domain checks
if not (isinstance(a,int) and isinstance(b,int) and isinstance(c,int)):
    return (False, None)
if a <= 0 or b <= 0 or c <= 0:
    return (False, None)
if not (isinstance(k,int) or isinstance(k,float)):
    return (False, None)
if k <= 0:
    return (False, None)
if not all(isinstance(v,int) for v in [A_num, A_den, B_num, B_den]):
    return (False, None)
if A_den == 0 or B_den == 0:
    return (False, None)
# Enforce difficulty: at least one exponent > 1 and k != 1
if a == 1 and b == 1 and c == 1:
    return (False, None)
if k == 1:
    return (False, None)
# Build A, B as rationals (numerator/denominator)
# Compute S = A + B + k + 1/k as a rational
den1 = A_den * B_den
# A + B = (A_num/A_den) + (B_num/B_den) = (A_num*B_den + B_num*A_den) / den1
sum_AB_num = A_num * B_den + B_num * A_den
sum_AB_den = den1
# Add k: bring to common denominator sum_AB_den
sum_ABk_num = sum_AB_num + int(round(k)) * sum_AB_den  # k is integral from generator
sum_ABk_den = sum_AB_den
# Add 1/k: now common denominator sum_AB_den * k
S_num = sum_ABk_num * int(round(k)) + sum_ABk_den
S_den = sum_ABk_den * int(round(k))
# Compute AB - 1 as rational: (A_num*B_num)/(A_den*B_den) - 1 = (A_num*B_num - A_den*B_den) / (A_den*B_den)
AB_num = A_num * B_num
AB_den = den1
ABm1_num = AB_num - AB_den
ABm1_den = AB_den
if ABm1_num == 0:
    # Denominator zero otherwise; invalid (too trivial)
    return (False, None)
# Then C = S / (AB - 1) => (S_num/S_den) / (ABm1_num/ABm1_den) = (S_num * ABm1_den) / (S_den * ABm1_num)
C_num = S_num * ABm1_den
C_den = S_den * ABm1_num
# Reduce C
g = gcd(C_num, C_den)
C_num_r = C_num // g
C_den_r = C_den // g
# Additional difficulty check: ensure non-integer
if C_den_r == 0:
    return (False, None)
if C_num_r % C_den_r == 0:
    return (False, None)
# If hidden true values exist, cross-check for consistency
if '_C_num' in assign and '_C_den' in assign:
    tnum = assign['_C_num']
    tden = assign['_C_den']
    # Reduce hidden fraction
    g2 = gcd(tnum, tden)
    tnum_r = tnum // g2
    tden_r = tden // g2
    # The computed C must match the hidden direct value
    if tnum_r != C_num_r or tden_r != C_den_r:
        # Inconsistency indicates a bad instance
        return (False, None)
answer = C_num_r + C_den_r
return (True, int(answer))


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

